const javaProgrammingPremiumEasyQs = [{"q":"Which of the following is the correct entry point of a standard Java application?","o":["`public void start(String[] args)`","`public static void main(String[] args)`","`static public void run(String args)`","`void main()`"],"a":1,"e":"The standard Java application entry point is `public static void main(String[] args)`."},{"q":"Which company originally developed Java?","o":["Microsoft","IBM","Sun Microsystems","Oracle"],"a":2,"e":"Java was originally developed at Sun Microsystems. Oracle later acquired Sun."},{"q":"Which keyword is used to create an object in Java?","o":["`class`","`new`","`this`","`object`"],"a":1,"e":"The `new` keyword creates an object and invokes its constructor."},{"q":"What is the default value of an instance variable of type `int` in Java?","o":["0","1","null","Undefined"],"a":0,"e":"Instance variables of primitive integer types default to zero."},{"q":"Which of the following is not a primitive data type in Java?","o":["`int`","`boolean`","`char`","`String`"],"a":3,"e":"`String` is a class, not a primitive data type."},{"q":"Which operator is used to compare two values for equality in Java?","o":["`=`","`==`","`!=`","`equals=`"],"a":1,"e":"`==` compares primitive values and checks reference identity for objects."},{"q":"What is the output of the following code?\n```\nint x = 10;\nint y = 3;\nSystem.out.println(x / y);\n```","o":["3.33","3","4","1"],"a":1,"e":"Integer division discards the fractional part, producing 3."},{"q":"Which loop executes its body at least once, even if its condition is initially false?","o":["`for`","`while`","`do-while`","Enhanced `for`"],"a":2,"e":"A `do-while` loop checks its condition after executing the loop body."},{"q":"Which keyword is used to inherit a class in Java?","o":["`implements`","`extends`","`inherits`","`super`"],"a":1,"e":"A class uses `extends` to inherit from another class."},{"q":"Which method is used to compare the contents of two Java strings?","o":["`==`","`compare()`","`equals()`","`same()`"],"a":2,"e":"`equals()` compares string contents, whereas `==` checks whether references identify the same object."},{"q":"Which of the following is the correct way to declare an integer array in Java?","o":["`int arr = new int[5];`","`int[] arr = new int[5];`","`array int arr = 5;`","`int arr[] = int[5];`"],"a":1,"e":"`int[] arr = new int[5];` declares and creates an integer array with five elements."},{"q":"What is the index of the first element in a Java array?","o":["1","-1","0","Depends on array size"],"a":2,"e":"Java arrays use zero-based indexing."},{"q":"Which keyword prevents a variable from being reassigned after initialization?","o":["`static`","`final`","`constant`","`fixed`"],"a":1,"e":"A `final` variable can be assigned only once."},{"q":"What is the output of this code?\n```\nint a = 5;\nSystem.out.println(++a);\n```","o":["5","6","4","Error"],"a":1,"e":"The pre-increment operator increases `a` before using its value."},{"q":"Which access modifier allows a member to be accessed from anywhere, subject to class accessibility?","o":["`private`","`protected`","Default","`public`"],"a":3,"e":"`public` provides the broadest member-level accessibility."},{"q":"Which keyword refers to the current object in Java?","o":["`super`","`this`","`self`","`current`"],"a":1,"e":"`this` refers to the current instance of the class."},{"q":"Which concept allows a class to have multiple methods with the same name but different parameter lists?","o":["Method overriding","Method overloading","Encapsulation","Abstraction"],"a":1,"e":"Method overloading uses the same method name with different parameter lists."},{"q":"Which of the following is used to handle exceptions in Java?","o":["`try-catch`","`if-else`","`for-while`","`switch-case`"],"a":0,"e":"A `try-catch` block handles exceptions that occur during execution."},{"q":"Which keyword is used to explicitly throw an exception?","o":["`throws`","`throw`","`catch`","`finally`"],"a":1,"e":"`throw` explicitly throws an exception object."},{"q":"Which keyword declares that a method may pass an exception to its caller?","o":["`throw`","`try`","`throws`","`finally`"],"a":2,"e":"`throws` appears in a method declaration to specify possible exceptions."},{"q":"Which class is commonly used to read text input from the keyboard in Java?","o":["`Scanner`","`Printer`","`FileWriter`","`StringBuilder`"],"a":0,"e":"`Scanner` can read keyboard input using `System.in`."},{"q":"Which package is automatically imported into every Java source file?","o":["`java.util`","`java.io`","`java.lang`","`java.net`"],"a":2,"e":"Classes from `java.lang`, such as `String`, `Math` and `System`, are automatically available."},{"q":"What is the output of this code?\n```\nString s = \"Java\";\nSystem.out.println(s.length());\n```","o":["3","4","5","Error"],"a":1,"e":"The string `\"Java\"` contains four characters."},{"q":"Which keyword is used to define a class that cannot be inherited?","o":["`static`","`abstract`","`final`","`private`"],"a":2,"e":"A class declared `final` cannot be extended."},{"q":"Which of the following is a valid Java comment for multiple lines?","o":["`// comment //`","`<!-- comment -->`","`/* comment */`","`## comment ##`"],"a":2,"e":"Java supports block comments using `/*` and `*/`."},{"q":"Which method is called automatically when an object is created?","o":["`main()`","Constructor","`finalize()`","`start()`"],"a":1,"e":"A constructor initializes a newly created object."},{"q":"Which statement about Java constructors is correct?","o":["A constructor must have a return type.","A constructor must always be private.","A constructor has the same name as its class.","A constructor must be static."],"a":2,"e":"A constructor has the same name as its class and does not declare a return type."},{"q":"What is the output of this code?\n```\nint x = 10;\nif (x > 5)\n    System.out.println(\"High\");\nelse\n    System.out.println(\"Low\");\n```","o":["Low","High","10","Error"],"a":1,"e":"Since 10 is greater than 5, the first branch executes."},{"q":"Which statement immediately terminates the current loop?","o":["`continue`","`skip`","`break`","`return`"],"a":2,"e":"`break` terminates the nearest enclosing loop or switch statement."},{"q":"Which statement skips the remaining statements in the current loop iteration?","o":["`break`","`continue`","`exit`","`stop`"],"a":1,"e":"`continue` moves control to the next loop iteration."},{"q":"Which class is the superclass of all Java classes, except `Object` itself?","o":["`String`","`Class`","`Object`","`System`"],"a":2,"e":"`java.lang.Object` is the root superclass of the Java class hierarchy."},{"q":"Which keyword is used when a class implements an interface?","o":["`extends`","`implements`","`interface`","`inherits`"],"a":1,"e":"A class uses `implements` to provide implementations for an interface's required methods."},{"q":"Which of the following is true about Java interfaces?","o":["An interface cannot contain methods.","An interface can be instantiated directly.","A class can implement multiple interfaces.","An interface must contain a constructor."],"a":2,"e":"Java supports implementing multiple interfaces in a single class."},{"q":"What is the output of this code?\n```\nint[] a = {2, 4, 6};\nSystem.out.println(a[1]);\n```","o":["2","4","6","1"],"a":1,"e":"Array indexing starts at zero, so `a[1]` accesses the second element."},{"q":"Which property of Java arrays specifies the number of elements?","o":["`size()`","`count()`","`length`","`capacity()`"],"a":2,"e":"Java arrays provide the `length` field to determine their size."},{"q":"Which class provides a mutable sequence of characters?","o":["`String`","`StringBuilder`","`Character`","`StringLiteral`"],"a":1,"e":"`StringBuilder` allows modifications without creating a new string for every operation."},{"q":"What is the output of this code?\n```\nString s = \"Programming\";\nSystem.out.println(s.charAt(0));\n```","o":["P","r","g","Error"],"a":0,"e":"`charAt(0)` returns the character at index zero."},{"q":"Which method converts a string to uppercase?","o":["`toUpper()`","`upperCase()`","`toUpperCase()`","`uppercase()`"],"a":2,"e":"Java's `String.toUpperCase()` returns an uppercase version of the string."},{"q":"Which wrapper class corresponds to the primitive type `int`?","o":["`Double`","`Integer`","`Long`","`Float`"],"a":1,"e":"`Integer` is the wrapper class for the primitive `int` type."},{"q":"What is autoboxing in Java?","o":["Converting an object into a primitive automatically","Automatically converting a primitive into its corresponding wrapper object","Converting a string into an integer","Allocating memory for an array"],"a":1,"e":"Autoboxing automatically converts a primitive value into its corresponding wrapper type."},{"q":"Which collection stores elements as key-value pairs?","o":["`ArrayList`","`HashSet`","`HashMap`","`LinkedList`"],"a":2,"e":"`HashMap` stores mappings between unique keys and values."},{"q":"Which collection does not allow duplicate elements?","o":["`ArrayList`","`HashSet`","`LinkedList`","`Vector`"],"a":1,"e":"A `HashSet` stores unique elements and does not maintain insertion order."},{"q":"Which interface is the root interface of the Java Collections Framework hierarchy for collections?","o":["`Collection`","`Map`","`Iterator`","`Comparable`"],"a":0,"e":"`Collection` is the root interface for collection types such as `List`, `Set` and `Queue`. `Map` is a separate hierarchy."},{"q":"Which method is used to add an element to an `ArrayList`?","o":["`insert()`","`push()`","`add()`","`append()`"],"a":2,"e":"`ArrayList.add()` adds an element to the list."},{"q":"What is the output of this code?\n```\nArrayList<Integer> list = new ArrayList<>();\nlist.add(10);\nlist.add(20);\nlist.remove(0);\nSystem.out.println(list);\n```","o":["`[10, 20]`","`[10]`","`[20]`","`[]`"],"a":2,"e":"`remove(0)` removes the element at index zero."},{"q":"Which interface provides the `hasNext()` and `next()` methods for traversing a collection?","o":["`Comparable`","`Iterator`","`Serializable`","`Runnable`"],"a":1,"e":"An `Iterator` provides methods for sequential traversal of collection elements."},{"q":"Which Java keyword is used to create a constant class-level variable?","o":["`const`","`static final`","`constant`","`volatile`"],"a":1,"e":"A `static final` field represents a class-level constant when initialized appropriately."},{"q":"Which keyword is used to prevent a method from being overridden in a subclass?","o":["`static`","`private`","`final`","`abstract`"],"a":2,"e":"A final method cannot be overridden by subclasses."},{"q":"What is method overriding?","o":["Defining multiple methods with different parameter lists in one class","Redefining an inherited method in a subclass with a compatible signature","Creating multiple constructors","Defining a method without a body"],"a":1,"e":"Overriding allows a subclass to provide a specialized implementation of an inherited method."},{"q":"Which concept allows the same reference type to refer to objects of different subclasses?","o":["Encapsulation","Polymorphism","Compilation","Serialization"],"a":1,"e":"Polymorphism allows a superclass reference to refer to different subclass objects and invoke their overridden behavior."},{"q":"Which keyword is used to call a superclass constructor from a subclass constructor?","o":["`this`","`parent`","`super`","`extends`"],"a":2,"e":"`super()` invokes a superclass constructor and must be the first statement in a constructor when used explicitly."},{"q":"Which type of inheritance is not supported directly through Java classes?","o":["Single inheritance","Multilevel inheritance","Hierarchical inheritance","Multiple inheritance"],"a":3,"e":"Java classes cannot extend multiple classes. Similar multiple-type inheritance can be achieved through interfaces."},{"q":"Which keyword is used to declare an abstract class?","o":["`virtual`","`abstract`","`interface`","`final`"],"a":1,"e":"An abstract class is declared using the `abstract` keyword and cannot be instantiated directly."},{"q":"Can an abstract class contain a constructor in Java?","o":["No, never","Yes","Only if it is final","Only if it has no methods"],"a":1,"e":"Abstract classes can have constructors, which are invoked during subclass object construction."},{"q":"Which exception is thrown when an array is accessed using an invalid index?","o":["`NullPointerException`","`ArrayIndexOutOfBoundsException`","`NumberFormatException`","`IOException`"],"a":1,"e":"Java throws this exception when an array index is negative or outside its valid range."},{"q":"Which of the following is a checked exception?","o":["`ArithmeticException`","`NullPointerException`","`IOException`","`ArrayIndexOutOfBoundsException`"],"a":2,"e":"`IOException` is checked at compile time and must be caught or declared."},{"q":"Which block is generally used to execute cleanup code whether an exception occurs or not?","o":["`try`","`catch`","`finally`","`throw`"],"a":2,"e":"The `finally` block normally executes after the try/catch processing, making it useful for cleanup."},{"q":"Which exception is commonly raised when an integer is divided by zero?","o":["`IOException`","`ArithmeticException`","`NumberFormatException`","`ClassCastException`"],"a":1,"e":"Integer division by zero in Java throws an `ArithmeticException`."},{"q":"Which class is commonly used to read characters from a text file efficiently?","o":["`BufferedReader`","`FileWriter`","`PrintWriter`","`ObjectOutputStream`"],"a":0,"e":"`BufferedReader` reads text efficiently by buffering characters and supports `readLine()`."},{"q":"Which class is used to write character data to a file?","o":["`FileReader`","`FileWriter`","`BufferedReader`","`Scanner`"],"a":1,"e":"`FileWriter` writes character-based data to a file."},{"q":"Which Java interface must a class implement to define a task that can be executed by a thread?","o":["`Serializable`","`Runnable`","`Comparable`","`Cloneable`"],"a":1,"e":"A class implementing `Runnable` provides a `run()` method containing the task."},{"q":"Which method starts a new thread of execution?","o":["`run()`","`execute()`","`start()`","`init()`"],"a":2,"e":"`start()` schedules a new thread and eventually invokes its `run()` method."},{"q":"What happens if the `run()` method of a `Thread` object is called directly?","o":["A new thread always starts","The method executes like an ordinary method call in the current thread","The JVM creates two threads","A compilation error occurs"],"a":1,"e":"Calling `run()` directly does not start a new thread; `start()` does."},{"q":"Which keyword can be used to prevent multiple threads from simultaneously executing a synchronized instance method on the same object?","o":["`volatile`","`transient`","`synchronized`","`native`"],"a":2,"e":"An instance synchronized method acquires the monitor lock of the current object."},{"q":"Which keyword is used to declare a variable whose value may be changed by different threads and should be read from shared memory?","o":["`final`","`volatile`","`static`","`transient`"],"a":1,"e":"`volatile` provides visibility guarantees for reads and writes to a variable across threads, but does not make compound operations atomic."},{"q":"Which class provides a fixed-size array-like structure that can grow dynamically?","o":["`String`","`ArrayList`","`Integer`","`Arrays`"],"a":1,"e":"`ArrayList` is a resizable array implementation of the `List` interface."},{"q":"Which collection maintains insertion order and allows duplicate elements?","o":["`HashSet`","`TreeSet`","`ArrayList`","`HashMap`"],"a":2,"e":"`ArrayList` preserves insertion order and allows duplicates."},{"q":"Which collection maintains elements in sorted order according to their natural ordering by default?","o":["`HashSet`","`TreeSet`","`ArrayList`","`LinkedHashSet`"],"a":1,"e":"`TreeSet` stores unique elements in sorted order by default."},{"q":"Which interface is used to define the natural ordering of objects?","o":["`Comparator`","`Iterator`","`Comparable`","`Cloneable`"],"a":2,"e":"A class implements `Comparable` and defines its natural ordering through `compareTo()`."},{"q":"Which interface is used to define an external custom ordering for objects?","o":["`Serializable`","`Comparator`","`Runnable`","`Collection`"],"a":1,"e":"`Comparator` defines custom comparison logic, commonly through `compare()`."},{"q":"What is the output of this code?\n```\nStringBuilder sb = new StringBuilder(\"Java\");\nsb.append(\" Programming\");\nSystem.out.println(sb);\n```","o":["Java","Programming","Java Programming","Error"],"a":2,"e":"`append()` adds characters to the existing `StringBuilder`."},{"q":"Which method converts a numeric string into an integer?","o":["`Integer.parseInt()`","`Integer.toString()`","`String.valueOf()`","`Integer.convert()`"],"a":0,"e":"`Integer.parseInt()` parses a valid integer representation from a string."},{"q":"What exception occurs when an invalid numeric string is passed to `Integer.parseInt()`?","o":["`ArithmeticException`","`NumberFormatException`","`IOException`","`ClassNotFoundException`"],"a":1,"e":"The method throws `NumberFormatException` if the input cannot be parsed as an integer."},{"q":"Which Java feature allows source code to use types as parameters, such as `List<String>`?","o":["Reflection","Generics","Serialization","Annotation"],"a":1,"e":"Generics enable type-safe classes, interfaces and methods using type parameters."},{"q":"Which symbol represents a wildcard type in Java generics?","o":["`#`","`&`","`?`","`*`"],"a":2,"e":"The `?` wildcard represents an unknown type in generic declarations."},{"q":"Which annotation indicates that a method is intended to override a superclass method?","o":["`@Inherited`","`@Override`","`@Deprecated`","`@FunctionalInterface`"],"a":1,"e":"`@Override` allows the compiler to check whether the method correctly overrides an inherited method."},{"q":"Which keyword is used to create a package declaration in a Java source file?","o":["`import`","`include`","`package`","`namespace`"],"a":2,"e":"The `package` statement declares the package to which a source file belongs."},{"q":"Which keyword is used to access classes from another package?","o":["`include`","`import`","`using`","`require`"],"a":1,"e":"The `import` statement allows classes and interfaces to be referenced without writing their fully qualified names."},{"q":"Which Java component is responsible for converting bytecode into machine-specific instructions during execution?","o":["JDK","JVM","Javadoc","Java compiler only"],"a":1,"e":"The JVM executes Java bytecode using interpretation and, where applicable, just-in-time compilation."},{"q":"Which tool is included in the JDK and is used to compile Java source files?","o":["`java`","`javac`","`javadoc`","`jar`"],"a":1,"e":"`javac` compiles `.java` source files into `.class` bytecode files."},{"q":"What is the extension of a compiled Java bytecode file?","o":["`.java`","`.exe`","`.class`","`.jar`"],"a":2,"e":"The Java compiler normally generates `.class` files containing bytecode."},{"q":"Which memory area stores objects created using `new` in the Java runtime?","o":["Stack","Heap","Program counter register","Method parameter area only"],"a":1,"e":"Objects and arrays are allocated in the heap, while local variables and method frames are generally managed on thread stacks."},{"q":"Which Java mechanism automatically reclaims memory occupied by unreachable objects?","o":["Destructor","Garbage collection","Manual deallocation","`final` keyword"],"a":1,"e":"The JVM's garbage collector reclaims memory from objects that are no longer reachable."},{"q":"Which of the following statements about Java strings is correct?","o":["Strings are mutable.","Strings are immutable.","Strings cannot contain spaces.","Strings are primitive data types."],"a":1,"e":"Once a `String` object is created, its contents cannot be changed."},{"q":"What is the output of this code?\n```\nString a = \"Java\";\nString b = \"Java\";\nSystem.out.println(a == b);\n```","o":["true","false","null","Compilation error"],"a":0,"e":"Identical string literals are interned, so both references refer to the same pooled object."},{"q":"Which class is used to represent a date without a time or time zone in modern Java?","o":["`Date`","`LocalDate`","`LocalTime`","`Calendar`"],"a":1,"e":"`java.time.LocalDate` represents a calendar date without a time or time zone."},{"q":"Which method is used to obtain the current date using the modern Java Date-Time API?","o":["`LocalDate.now()`","`LocalDate.current()`","`Date.getToday()`","`Calendar.today()`"],"a":0,"e":"`LocalDate.now()` returns the current date using the system's default time zone."},{"q":"Which Java interface represents a function that accepts one argument and produces a result?","o":["`Runnable`","`Consumer`","`Function`","`Supplier`"],"a":2,"e":"`Function<T, R>` represents a function that accepts a value of type T and returns a value of type R."},{"q":"Which functional interface represents an operation that accepts an argument and returns no result?","o":["`Predicate`","`Consumer`","`Supplier`","`Function`"],"a":1,"e":"`Consumer<T>` accepts an argument and performs an operation without returning a result."},{"q":"Which functional interface returns a boolean result after testing an input?","o":["`Predicate`","`Supplier`","`Runnable`","`Consumer`"],"a":0,"e":"`Predicate<T>` represents a condition that returns a boolean value."},{"q":"Which Java Stream operation filters elements based on a condition?","o":["`map()`","`reduce()`","`filter()`","`collect()`"],"a":2,"e":"`filter()` retains stream elements that satisfy the specified predicate."},{"q":"Which Stream operation transforms each element into another value?","o":["`filter()`","`map()`","`count()`","`forEach()`"],"a":1,"e":"`map()` applies a transformation function to every element in a stream."},{"q":"Which Stream operation combines elements into a single result using an accumulation operation?","o":["`filter()`","`sorted()`","`reduce()`","`distinct()`"],"a":2,"e":"`reduce()` combines stream elements into one result, such as a sum or product."},{"q":"Which keyword declares a method that belongs to the class rather than to individual objects?","o":["`final`","`static`","`abstract`","`volatile`"],"a":1,"e":"A static method belongs to the class and can be called using the class name."},{"q":"Which statement about a static method is correct?","o":["It can directly access instance variables without an object.","It can directly access only static members of its class.","It must always be private.","It cannot accept parameters."],"a":1,"e":"A static method has no implicit `this` reference, so it cannot directly access instance members."},{"q":"Which Java feature allows an object to be converted into a byte stream for storage or transmission?","o":["Inheritance","Serialization","Encapsulation","Overloading"],"a":1,"e":"Serialization converts an object's state into a byte stream. Java commonly uses `Serializable` and object streams for this purpose."},{"q":"Which interface is commonly implemented by a class whose objects can be serialized using Java's standard object serialization mechanism?","o":["`Runnable`","`Cloneable`","`Serializable`","`Comparable`"],"a":2,"e":"A class generally implements `Serializable` to indicate that its instances can be serialized."},{"q":"Which keyword prevents a field from being included in the default Java serialization process?","o":["`static`","`volatile`","`transient`","`synchronized`"],"a":2,"e":"The default serialization mechanism skips transient instance fields."},{"q":"Which JDBC interface represents a connection to a database?","o":["`Statement`","`ResultSet`","`Connection`","`Driver`"],"a":2,"e":"JDBC's `Connection` interface represents an active database connection."},{"q":"Which JDBC interface is commonly used to execute parameterized SQL queries?","o":["`Statement`","`PreparedStatement`","`ResultSet`","`DatabaseMetaData`"],"a":1,"e":"`PreparedStatement` supports parameterized SQL and helps prevent SQL injection when parameters are bound correctly."}];
const javaProgrammingPremiumModerateQs = [{"q":"What is the output of the following Java code?\n```\nint a = 10;\nint b = 20;\nSystem.out.println(a > b ? a : b);\n```","o":["10","20","true","false"],"a":1,"e":"The ternary operator returns `b` because `a > b` is false."},{"q":"What happens when a subclass defines a static method with the same signature as a static method in its superclass?","o":["Method overriding occurs","Method hiding occurs","Compilation always fails","Runtime polymorphism occurs"],"a":1,"e":"Static methods are hidden rather than overridden because they belong to classes."},{"q":"Which keyword is used to invoke another constructor in the same class?","o":["`super()`","`this()`","`extends`","`new()`"],"a":1,"e":"`this()` invokes another constructor in the same class and must be the first constructor statement."},{"q":"What is the output of this code?\n```\nString s1 = new String(\"Java\");\nString s2 = new String(\"Java\");\nSystem.out.println(s1.equals(s2));\n```","o":["true","false","null","Compilation error"],"a":0,"e":"`equals()` compares string contents rather than object references."},{"q":"Which statement about Java's `HashMap` is correct?","o":["It does not allow null values.","It maintains keys in sorted order.","It permits one null key and multiple null values.","It allows duplicate keys."],"a":2,"e":"A `HashMap` permits one null key and multiple null values. A new value replaces the previous value for an existing key."},{"q":"Which collection is suitable when insertion order must be preserved while storing unique elements?","o":["`HashSet`","`TreeSet`","`LinkedHashSet`","`PriorityQueue`"],"a":2,"e":"`LinkedHashSet` maintains insertion order while preventing duplicate elements."},{"q":"What is the output of this code?\n```\nint x = 5;\nSystem.out.println(x++ + ++x);\n```","o":["10","11","12","13"],"a":2,"e":"`x++` contributes 5 and changes x to 6. `++x` then changes x to 7 and contributes 7. Total = 12."},{"q":"Which exception is thrown when an application tries to access a method using a null reference?","o":["`IOException`","`NullPointerException`","`ArithmeticException`","`ClassCastException`"],"a":1,"e":"Dereferencing a null reference causes a `NullPointerException`."},{"q":"Which statement about an abstract method is correct?","o":["It must have a method body.","It cannot have parameters.","It is declared without an implementation body.","It must be static."],"a":2,"e":"An abstract method declares a method signature without providing its implementation."},{"q":"What is the output of this code?\n```\nint[] arr = {10, 20, 30, 40};\nSystem.out.println(arr.length);\n```","o":["3","4","5","40"],"a":1,"e":"The array contains four elements, and its `length` field returns 4."},{"q":"Which collection is backed by a doubly linked list?","o":["`ArrayList`","`HashSet`","`LinkedList`","`TreeMap`"],"a":2,"e":"Java's `LinkedList` is implemented as a doubly linked list."},{"q":"Which method is used to check whether a collection contains a particular element?","o":["`exists()`","`contains()`","`search()`","`find()`"],"a":1,"e":"The `contains()` method checks whether the specified element exists in a collection."},{"q":"What is the output of this code?\n```\nint x = 10;\nint y = 10;\nSystem.out.println(x == y);\n```","o":["true","false","10","Error"],"a":0,"e":"The `==` operator compares primitive values directly."},{"q":"Which interface must a class implement to be used as a target of a lambda expression with one abstract method?","o":["Marker interface","Functional interface","Serializable interface only","Abstract class"],"a":1,"e":"A functional interface has exactly one abstract method and can serve as a lambda expression target."},{"q":"Which annotation is used to indicate that an interface is intended to be a functional interface?","o":["`@Override`","`@FunctionalInterface`","`@Interface`","`@Lambda`"],"a":1,"e":"The annotation enables compile-time checking of the single-abstract-method requirement."},{"q":"What is the output of this code?\n```\nArrayList<String> list = new ArrayList<>();\nlist.add(\"A\");\nlist.add(\"B\");\nlist.add(\"C\");\nSystem.out.println(list.get(2));\n```","o":["A","B","C","Error"],"a":2,"e":"Index 2 refers to the third element."},{"q":"Which method removes all elements from an `ArrayList`?","o":["`remove()`","`clear()`","`delete()`","`empty()`"],"a":1,"e":"`clear()` removes every element from the list."},{"q":"What is the purpose of the `finally` block in Java?","o":["It executes only when an exception occurs.","It executes only when no exception occurs.","It provides cleanup code after try/catch processing.","It creates a new exception."],"a":2,"e":"A `finally` block normally executes whether or not an exception occurs."},{"q":"Which of the following is an unchecked exception?","o":["`SQLException`","`IOException`","`ClassNotFoundException`","`IllegalArgumentException`"],"a":3,"e":"`IllegalArgumentException` is a subclass of `RuntimeException`."},{"q":"What is the output of this code?\n```\nString s = \"Hello\";\nSystem.out.println(s.substring(1, 4));\n```","o":["Hel","ell","ello","Error"],"a":1,"e":"`substring(1, 4)` includes index 1 and excludes index 4."},{"q":"Which class is commonly used to store key-value pairs in sorted key order?","o":["`HashMap`","`TreeMap`","`LinkedHashMap`","`ArrayList`"],"a":1,"e":"`TreeMap` stores keys in sorted order according to their natural ordering or a supplied comparator."},{"q":"Which method can be used to sort a list in Java?","o":["`Collections.sort()`","`List.order()`","`ArrayList.arrange()`","`System.sort()`"],"a":0,"e":"`Collections.sort()` sorts a list according to natural ordering or a provided comparator."},{"q":"Which interface provides a mechanism for comparing two objects using custom comparison logic?","o":["`Comparable`","`Comparator`","`Iterable`","`Cloneable`"],"a":1,"e":"`Comparator` allows ordering to be defined independently of the object's natural ordering."},{"q":"What is the output of this code?\n```\nint[] a = {1, 2, 3};\nint[] b = a;\nb[0] = 100;\nSystem.out.println(a[0]);\n```","o":["1","2","100","Error"],"a":2,"e":"Both variables refer to the same array object."},{"q":"Which method is used to obtain the number of elements in an `ArrayList`?","o":["`length`","`size()`","`count()`","`capacity()`"],"a":1,"e":"The `size()` method returns the number of elements currently stored in the list."},{"q":"What is the output of this code?\n```\nint x = 5;\nSystem.out.println(x += 3);\n```","o":["5","3","8","15"],"a":2,"e":"The compound assignment adds 3 to x and prints the updated value."},{"q":"Which of the following is true about Java constructors?","o":["Constructors can be inherited.","Constructors can be overridden.","Constructors can be overloaded.","Constructors must be static."],"a":2,"e":"A class can define multiple constructors with different parameter lists."},{"q":"Which keyword is used to declare a member that belongs to the class rather than an instance?","o":["`final`","`static`","`transient`","`volatile`"],"a":1,"e":"Static members belong to the class and are shared across instances."},{"q":"Which of the following cannot be declared as an abstract method?","o":["Instance method","Method in an abstract class","Private method","Method in an interface"],"a":2,"e":"A private method cannot be abstract because an abstract method must be implemented by a subclass or implementing class, which cannot access it."},{"q":"Which statement about Java interfaces is correct?","o":["Interfaces can have constructors.","Interfaces can contain default methods.","Interfaces can be instantiated directly.","Interfaces cannot extend other interfaces."],"a":1,"e":"Since Java 8, interfaces can define default methods with implementations."},{"q":"What is the output of this code?\n```\nString s = \"Java\";\ns.concat(\" Programming\");\nSystem.out.println(s);\n```","o":["Java Programming","Programming","Java","null"],"a":2,"e":"Strings are immutable. `concat()` returns a new string, but its result is not assigned to `s`."},{"q":"Which class is suitable for building strings in a multithreaded environment when synchronized operations are needed?","o":["`String`","`StringBuilder`","`StringBuffer`","`Character`"],"a":2,"e":"`StringBuffer` provides synchronized methods, while `StringBuilder` is generally faster when synchronization is unnecessary."},{"q":"Which method converts a primitive integer into its string representation?","o":["`Integer.parseInt()`","`String.valueOf()`","`Integer.toInt()`","`String.parse()`"],"a":1,"e":"`String.valueOf(int)` returns the textual representation of the integer."},{"q":"Which exception is thrown when an invalid cast between incompatible reference types is attempted at runtime?","o":["`ClassCastException`","`IllegalStateException`","`NumberFormatException`","`IndexOutOfBoundsException`"],"a":0,"e":"An incompatible reference cast causes a `ClassCastException` at runtime."},{"q":"What is the output of this code?\n```\nint x = 10;\nSystem.out.println(x > 5 && x < 15);\n```","o":["true","false","10","Error"],"a":0,"e":"Both conditions are true, so the logical AND evaluates to true."},{"q":"Which Java class provides a thread-safe implementation of a key-value map with concurrent access support?","o":["`HashMap`","`TreeMap`","`ConcurrentHashMap`","`LinkedHashMap`"],"a":2,"e":"`ConcurrentHashMap` supports concurrent access without requiring the entire map to be externally synchronized for each operation."},{"q":"Which method causes the current thread to pause for a specified number of milliseconds?","o":["`wait()`","`sleep()`","`join()`","`yield()`"],"a":1,"e":"`Thread.sleep()` pauses the current thread for the specified duration, subject to scheduling."},{"q":"Which method causes the current thread to wait until another thread completes?","o":["`sleep()`","`wait()`","`join()`","`notify()`"],"a":2,"e":"`join()` waits for the target thread to terminate."},{"q":"Which method releases the monitor lock while a thread waits for a notification?","o":["`sleep()`","`wait()`","`yield()`","`join()`"],"a":1,"e":"`wait()` releases the object's monitor and waits until notified or otherwise interrupted."},{"q":"Which method is used to wake one thread waiting on an object's monitor?","o":["`notify()`","`sleep()`","`interrupt()`","`start()`"],"a":0,"e":"`notify()` wakes one thread waiting on the object's monitor."},{"q":"Which JDBC method is used to execute an SQL `SELECT` query using a `Statement` object?","o":["`executeUpdate()`","`executeQuery()`","`executeInsert()`","`getQuery()`"],"a":1,"e":"`executeQuery()` executes a query that returns a `ResultSet`."},{"q":"Which JDBC method is commonly used to execute SQL `INSERT`, `UPDATE` and `DELETE` statements?","o":["`executeQuery()`","`executeUpdate()`","`getResult()`","`executeSelect()`"],"a":1,"e":"`executeUpdate()` returns the number of affected rows for typical data modification statements."},{"q":"Which JDBC interface represents the result of a SQL query?","o":["`Connection`","`Statement`","`ResultSet`","`DriverManager`"],"a":2,"e":"`ResultSet` stores the tabular results returned by a query."},{"q":"Which JDBC class is used to obtain a database connection using a JDBC URL?","o":["`DriverManager`","`ResultSet`","`PreparedStatement`","`DatabaseMetaData`"],"a":0,"e":"`DriverManager.getConnection()` obtains a connection using a JDBC URL and credentials."},{"q":"Which feature of `PreparedStatement` helps prevent SQL injection?","o":["String concatenation","Parameter binding","Manual query formatting","Dynamic class loading"],"a":1,"e":"Parameterized queries separate SQL structure from user-supplied values."},{"q":"What is the output of this code?\n```\nList<Integer> nums = Arrays.asList(1, 2, 3, 4);\nlong count = nums.stream().filter(n -> n > 2).count();\nSystem.out.println(count);\n```","o":["1","2","3","4"],"a":1,"e":"The elements greater than 2 are 3 and 4."},{"q":"Which Java Stream method converts a stream into a collection or another container?","o":["`filter()`","`map()`","`collect()`","`sorted()`"],"a":2,"e":"`collect()` performs a mutable reduction, often producing lists, sets or maps."},{"q":"Which Stream method removes duplicate elements from a stream?","o":["`unique()`","`distinct()`","`remove()`","`deduplicate()`"],"a":1,"e":"`distinct()` returns a stream containing distinct elements according to their equality."},{"q":"Which Stream operation sorts elements in their natural order by default?","o":["`order()`","`sort()`","`sorted()`","`arrange()`"],"a":2,"e":"`sorted()` produces an ordered stream using natural ordering unless a comparator is supplied."},{"q":"What is the output of this code?\n```\nList<Integer> nums = Arrays.asList(3, 1, 2);\nnums.stream().sorted().forEach(System.out::print);\n```","o":["312","123","321","Error"],"a":1,"e":"`sorted()` arranges the stream elements in ascending order before printing."},{"q":"Which functional interface accepts no arguments and returns a result?","o":["`Consumer`","`Supplier`","`Predicate`","`BiConsumer`"],"a":1,"e":"`Supplier<T>` provides a value through its `get()` method without accepting arguments."},{"q":"Which Java Stream method is used to find the first element of a stream?","o":["`first()`","`findFirst()`","`getFirst()`","`start()`"],"a":1,"e":"`findFirst()` returns an `Optional` containing the first element, if one exists."},{"q":"What is the output of this code?\n```\nOptional<String> name = Optional.of(\"Java\");\nSystem.out.println(name.orElse(\"Python\"));\n```","o":["Python","Java","null","Error"],"a":1,"e":"Since the `Optional` contains `\"Java\"`, `orElse()` returns that value."},{"q":"Which Java class is used to represent a date and time with a time zone?","o":["`LocalDateTime`","`LocalDate`","`ZonedDateTime`","`LocalTime`"],"a":2,"e":"`ZonedDateTime` represents date and time information with a time zone."},{"q":"Which class is commonly used to format dates using patterns in the modern Java Date-Time API?","o":["`DateFormat`","`SimpleDateFormat`","`DateTimeFormatter`","`CalendarFormatter`"],"a":2,"e":"`DateTimeFormatter` formats and parses modern Java date-time objects."},{"q":"Which Java keyword indicates that a class cannot be subclassed?","o":["`abstract`","`final`","`static`","`protected`"],"a":1,"e":"A final class cannot be extended."},{"q":"Which access modifier makes a member accessible only within its declaring class?","o":["`public`","`protected`","Default","`private`"],"a":3,"e":"Private members are accessible only within the declaring top-level class, subject to Java's nested-class access rules."},{"q":"Which access level is used when no access modifier is specified?","o":["`public`","`private`","Package-private","`protected`"],"a":2,"e":"Without an explicit modifier, a member is accessible within its package."},{"q":"What is the output of this code?\n```\nint a = 10;\nint b = 3;\nSystem.out.println(a % b);\n```","o":["1","2","3","0"],"a":0,"e":"The remainder of 10 divided by 3 is 1."},{"q":"Which keyword is used to define a variable that cannot be reassigned after initialization?","o":["`static`","`final`","`volatile`","`transient`"],"a":1,"e":"A final variable can be assigned only once."},{"q":"Which statement about `ArrayList` and `LinkedList` is correct?","o":["Both are fixed-size collections.","`ArrayList` uses a dynamic array internally, while `LinkedList` uses linked nodes.","`LinkedList` does not allow duplicate elements.","`ArrayList` maintains sorted order automatically."],"a":1,"e":"The two classes use different underlying data structures and have different performance characteristics."},{"q":"Which collection provides a FIFO queue implementation with elements inserted at the end and removed from the front?","o":["`HashSet`","`ArrayDeque`","`TreeMap`","`HashMap`"],"a":1,"e":"`ArrayDeque` supports queue operations such as `offer()` and `poll()`."},{"q":"Which method retrieves and removes the head of a queue, returning null if the queue is empty?","o":["`element()`","`remove()`","`poll()`","`peek()`"],"a":2,"e":"`poll()` retrieves and removes the head or returns null if no element is available."},{"q":"Which method retrieves the head of a queue without removing it, returning null if the queue is empty?","o":["`poll()`","`peek()`","`remove()`","`offer()`"],"a":1,"e":"`peek()` examines the head without removing it."},{"q":"Which Java class is used to create a priority queue?","o":["`PriorityQueue`","`PriorityList`","`QueueArray`","`TreeList`"],"a":0,"e":"`PriorityQueue` orders elements according to their natural ordering or a supplied comparator."},{"q":"What is the default ordering of a Java `PriorityQueue<Integer>`?","o":["Descending","Random","Ascending priority, with the smallest element at the head","Insertion order"],"a":2,"e":"The default natural ordering makes the smallest integer the head of the priority queue."},{"q":"Which method can be used to convert a collection into an array?","o":["`toArray()`","`convertArray()`","`asArray()`","`getArray()`"],"a":0,"e":"The `toArray()` method converts a collection into an array."},{"q":"Which exception is commonly thrown when a thread is interrupted while sleeping or waiting?","o":["`IOException`","`InterruptedException`","`IllegalThreadStateException`","`ThreadDeath`"],"a":1,"e":"Blocking methods such as `sleep()` and `wait()` can throw `InterruptedException`."},{"q":"Which method can be used to request interruption of a thread?","o":["`stop()`","`interrupt()`","`terminate()`","`kill()`"],"a":1,"e":"`interrupt()` sets the thread's interrupt status and may cause certain blocking methods to throw `InterruptedException`."},{"q":"Which method returns the current thread object?","o":["`Thread.currentThread()`","`Thread.getCurrent()`","`Thread.active()`","`Thread.getThread()`"],"a":0,"e":"This static method returns the thread currently executing the code."},{"q":"Which interface represents a task that returns a result and may throw a checked exception when executed through an executor?","o":["`Runnable`","`Callable`","`Consumer`","`Comparator`"],"a":1,"e":"`Callable<V>` returns a result and its `call()` method may throw checked exceptions."},{"q":"Which Java class manages a pool of worker threads?","o":["`ExecutorService`","`StringBuffer`","`FileReader`","`Scanner`"],"a":0,"e":"`ExecutorService` manages task execution using thread pools and provides lifecycle management methods."},{"q":"Which method is used to submit a `Callable` task to an `ExecutorService` and obtain a `Future`?","o":["`execute()`","`submit()`","`run()`","`start()`"],"a":1,"e":"`submit()` accepts a `Callable` and returns a `Future` representing its pending result."},{"q":"Which Java class is commonly used to read raw bytes from a file?","o":["`FileReader`","`FileInputStream`","`BufferedReader`","`FileWriter`"],"a":1,"e":"`FileInputStream` reads byte-oriented data from a file."},{"q":"Which class is commonly used to write raw bytes to a file?","o":["`FileOutputStream`","`FileReader`","`BufferedReader`","`Scanner`"],"a":0,"e":"`FileOutputStream` writes byte-oriented data to a file."},{"q":"Which Java feature enables an object to be written to an output stream as a byte sequence?","o":["Reflection","Serialization","Inheritance","Compilation"],"a":1,"e":"Serialization converts an object's state into a byte stream for storage or transmission."},{"q":"Which interface is required for an object to participate in Java's standard serialization mechanism?","o":["`Cloneable`","`Comparable`","`Serializable`","`Runnable`"],"a":2,"e":"A class generally implements `Serializable` to indicate that its instances can be serialized."},{"q":"Which Java keyword prevents a field from being included in default serialization?","o":["`static`","`transient`","`volatile`","`final`"],"a":1,"e":"The default serialization mechanism skips transient instance fields."},{"q":"Which class is used to read serialized objects from an input stream?","o":["`ObjectInputStream`","`ObjectOutputStream`","`BufferedInputStream`","`FileReader`"],"a":0,"e":"`ObjectInputStream` reads objects from a serialized byte stream."},{"q":"Which class is used to write serialized objects to an output stream?","o":["`ObjectInputStream`","`ObjectOutputStream`","`FileReader`","`BufferedReader`"],"a":1,"e":"`ObjectOutputStream` writes objects to an output stream using Java serialization."},{"q":"What is the output of this code?\n```\nString s = \"Java\";\nSystem.out.println(s.indexOf('a'));\n```","o":["0","1","2","3"],"a":1,"e":"The first lowercase `a` appears at index 1."},{"q":"Which method checks whether a string contains a specified sequence of characters?","o":["`has()`","`contains()`","`includes()`","`match()`"],"a":1,"e":"`String.contains()` checks whether the specified character sequence occurs within the string."},{"q":"Which method splits a string into an array using a regular-expression delimiter?","o":["`substring()`","`split()`","`divide()`","`tokenize()`"],"a":1,"e":"`String.split()` uses a regular expression to divide a string into an array."},{"q":"What is the output of this code?\n```\nString s = \"apple,banana,orange\";\nString[] arr = s.split(\",\");\nSystem.out.println(arr.length);\n```","o":["2","3","4","19"],"a":1,"e":"The comma delimiter creates three substrings."},{"q":"Which Java class provides methods for performing mathematical operations such as square root and power?","o":["`Integer`","`Math`","`Number`","`System`"],"a":1,"e":"`java.lang.Math` provides static methods such as `sqrt()`, `pow()` and `abs()`."},{"q":"What is the output of this code?\n```\nSystem.out.println(Math.max(12, 25));\n```","o":["12","25","37","13"],"a":1,"e":"`Math.max()` returns the larger of its two arguments."},{"q":"Which Java method generates a pseudo-random `double` between 0.0 inclusive and 1.0 exclusive?","o":["`Math.random()`","`Math.randomInt()`","`Random.nextInt()`","`System.random()`"],"a":0,"e":"`Math.random()` returns a pseudo-random double in the interval [0.0, 1.0)."},{"q":"Which operator is used to check whether an object belongs to a particular type?","o":["`typeof`","`instanceof`","`is`","`typecheck`"],"a":1,"e":"`instanceof` tests whether an object is an instance of a specified type or its subtype."},{"q":"Which statement about the `instanceof` operator is correct?","o":["It compares object contents.","It checks type compatibility at runtime.","It creates a new object.","It converts one primitive type into another."],"a":1,"e":"`instanceof` checks whether a reference is compatible with a specified type."},{"q":"Which Java feature allows an enum to contain fields, constructors and methods?","o":["Enums cannot contain methods.","Enums can contain fields, constructors and methods.","Enums must extend another enum.","Enums cannot implement interfaces."],"a":1,"e":"Java enums are specialized classes and can contain fields, constructors, methods and implement interfaces."},{"q":"Which method returns all enum constants in the order they were declared?","o":["`values()`","`getValues()`","`constants()`","`enumList()`"],"a":0,"e":"The compiler provides a static `values()` method for each enum type."},{"q":"Which Java feature allows a method to accept a variable number of arguments?","o":["Generics","Varargs","Overriding","Serialization"],"a":1,"e":"Varargs use `...` in a method parameter declaration to accept zero or more arguments of a specified type."},{"q":"What is the output of this code?\n```\nstatic int sum(int... nums) {\n    int total = 0;\n    for (int n : nums) {\n        total += n;\n    }\n    return total;\n}\n// Inside main:\nSystem.out.println(sum(1, 2, 3, 4));\n```","o":["4","6","10","Compilation error"],"a":2,"e":"The varargs parameter receives four integers, whose sum is 10."},{"q":"Which Java keyword is used to define a method that does not return any value?","o":["`null`","`void`","`empty`","`static`"],"a":1,"e":"A method declared `void` does not return a value."},{"q":"Which type of binding is associated with overridden instance methods when the actual method is selected at runtime?","o":["Static binding","Dynamic binding","Early compilation","Variable binding"],"a":1,"e":"The JVM selects the overridden instance method based on the actual object's runtime type."},{"q":"Which class can be used to store a thread's result when using `ExecutorService.submit()`?","o":["`Future`","`ThreadLocal`","`Scanner`","`Optional`"],"a":0,"e":"A `Future` represents the result of an asynchronous computation and provides methods such as `get()`."},{"q":"Which method is used to explicitly shut down an `ExecutorService` so that no new tasks are accepted while submitted tasks are allowed to finish?","o":["`stop()`","`shutdown()`","`terminate()`","`closeAll()`"],"a":1,"e":"`shutdown()` initiates an orderly shutdown and allows previously submitted tasks to complete."},{"q":"Which Java API is commonly used to execute SQL transactions?","o":["`Connection`","`Scanner`","`FileWriter`","`ArrayList`"],"a":0,"e":"JDBC transactions are managed through a `Connection`, using methods such as `setAutoCommit()`, `commit()` and `rollback()`."},{"q":"Which JDBC method reverses the changes made in the current transaction?","o":["`commit()`","`rollback()`","`executeQuery()`","`close()`"],"a":1,"e":"`rollback()` undoes uncommitted changes in the current transaction."},{"q":"Which JDBC setting disables automatic transaction commits?","o":["`setAutoCommit(false)`","`setTransaction(true)`","`disableCommit()`","`setRollback(true)`"],"a":0,"e":"Disabling auto-commit allows multiple SQL operations to be grouped into a transaction and committed or rolled back explicitly."}];
const javaProgrammingPremiumHardQs = [{"q":"What is the output of the following Java code?\n```\nclass A {\n    int x = 10;\n    void display() {\n        System.out.println(x);\n    }\n}\nclass B extends A {\n    int x = 20;\n    void display() {\n        System.out.println(super.x);\n    }\n}\npublic class Main {\n    public static void main(String[] args) {\n        A obj = new B();\n        obj.display();\n    }\n}\n```","o":["10","20","30","Compilation error"],"a":0,"e":"The overridden method in `B` executes, but `super.x` explicitly accesses the superclass field."},{"q":"What is the output of this code?\n```\nclass Test {\n    static int count = 0;\n    Test() {\n        count++;\n    }\n    public static void main(String[] args) {\n        Test a = new Test();\n        Test b = new Test();\n        Test c = new Test();\n        System.out.println(c.count);\n    }\n}\n```","o":["0","1","2","3"],"a":3,"e":"The static variable is shared by all instances and increments each time a constructor executes."},{"q":"Which statement about Java's method overriding is correct?","o":["An overriding method must have a more restrictive access modifier.","An overriding method cannot have a covariant return type.","An overriding method cannot reduce the visibility of the inherited method.","An overriding method must have a different parameter list."],"a":2,"e":"An overriding method must not reduce accessibility and may use a covariant reference return type."},{"q":"What is the output of this code?\n```\nclass A {\n    A() {\n        show();\n    }\n    void show() {\n        System.out.println(\"A\");\n    }\n}\nclass B extends A {\n    int x = 10;\n    void show() {\n        System.out.println(x);\n    }\n}\npublic class Main {\n    public static void main(String[] args) {\n        new B();\n    }\n}\n```","o":["10","0","A","Compilation error"],"a":1,"e":"The superclass constructor invokes the overridden method before subclass field initializers execute. The instance field `x` still has its default value of zero."},{"q":"Which Java collection provides average constant-time lookup by key under suitable hash distribution?","o":["`TreeMap`","`LinkedList`","`HashMap`","`TreeSet`"],"a":2,"e":"Hash-based lookup in `HashMap` has average O(1) complexity under suitable conditions."},{"q":"What happens when two different objects used as `HashMap` keys have equal hash codes but are not equal according to `equals()`?","o":["One key automatically replaces the other.","Both keys can exist in the map.","The map throws an exception.","The map rejects both keys."],"a":1,"e":"Hash codes help locate buckets, while `equals()` distinguishes keys within a bucket."},{"q":"Which contract should be maintained when overriding `equals()` and `hashCode()`?","o":["Equal objects must have different hash codes.","Unequal objects must have identical hash codes.","Equal objects must have the same hash code.","Both methods must always return zero."],"a":2,"e":"If two objects are equal according to `equals()`, they must produce the same hash code."},{"q":"What is the output of the following code?\n```\nList<Integer> list = new ArrayList<>();\nlist.add(10);\nlist.add(20);\nlist.add(30);\nlist.remove(Integer.valueOf(20));\nSystem.out.println(list);\n```","o":["`[10, 20]`","`[20, 30]`","`[10, 30]`","`[]`"],"a":2,"e":"`remove(Integer.valueOf(20))` selects the object-removal overload rather than the index-removal overload."},{"q":"Which statement about `TreeMap` is correct?","o":["It always preserves insertion order.","It sorts keys using natural ordering or a comparator.","It permits duplicate keys.","It is implemented using a hash table."],"a":1,"e":"`TreeMap` maintains keys in sorted order, typically using a red-black tree."},{"q":"What is the output of this code?\n```\nList<Integer> list = Arrays.asList(1, 2, 3);\nlist.set(1, 10);\nSystem.out.println(list);\n```","o":["`[1, 2, 3]`","`[1, 10, 3]`","`[10, 2, 3]`","Unsupported operation exception"],"a":1,"e":"`Arrays.asList()` returns a fixed-size list that supports replacing existing elements using `set()`."},{"q":"Which statement about `Arrays.asList()` is correct?","o":["It always returns a fully resizable `ArrayList`.","It returns a fixed-size list backed by the supplied array.","It returns an immutable list.","It automatically removes duplicate values."],"a":1,"e":"Changes to the list's existing elements are reflected in the backing array, but adding or removing elements is unsupported."},{"q":"What is the output of this code?\n```\nint x = 10;\nSystem.out.println(x++ + x++);\n```","o":["20","21","22","23"],"a":1,"e":"The first expression contributes 10, and the second contributes 11. The result is 21."},{"q":"Which generic declaration accepts a list of any type that is a subtype of `Number`?","o":["`List<? extends Number>`","`List<? super Number>`","`List<Number extends ?>`","`List<Number>`"],"a":0,"e":"The upper-bounded wildcard allows a list whose element type is `Number` or one of its subclasses."},{"q":"Which generic declaration is suitable for a method that inserts integer values into a list of `Number` or one of its supertypes?","o":["`List<? extends Number>`","`List<? super Integer>`","`List<?>`","`List<? extends Integer>`"],"a":1,"e":"A lower-bounded wildcard accepts `Integer` and its supertypes, allowing integer insertion."},{"q":"What is the output of this code?\n```\nList<String> list = new ArrayList<>();\nlist.add(\"A\");\nlist.add(\"B\");\nIterator<String> it = list.iterator();\nwhile (it.hasNext()) {\n    if (it.next().equals(\"A\")) {\n        it.remove();\n    }\n}\nSystem.out.println(list);\n```","o":["`[A, B]`","`[A]`","`[B]`","Concurrent modification exception"],"a":2,"e":"`Iterator.remove()` safely removes the last element returned by that iterator."},{"q":"What exception may occur if a collection is structurally modified outside an iterator while iterating with a fail-fast iterator?","o":["`IOException`","`ConcurrentModificationException`","`NullPointerException`","`IllegalArgumentException`"],"a":1,"e":"Fail-fast iterators may detect unexpected structural modifications and throw this exception."},{"q":"Which method is used to make an immutable copy of a collection in modern Java?","o":["`Collections.mutableCopy()`","`List.copyOf()`","`Arrays.asList()`","`Collections.sort()`"],"a":1,"e":"`List.copyOf()` returns an unmodifiable list containing the elements of the source collection."},{"q":"What is the output of the following code?\n```\nString s = \"Java\";\nString t = s.intern();\nSystem.out.println(s == t);\n```","o":["true","false","null","Compilation error"],"a":0,"e":"The literal `\"Java\"` is already interned, and `intern()` returns the canonical pooled string reference."},{"q":"Which Java memory area stores class-level metadata and runtime constant-pool information?","o":["Java heap","Java stack","Metaspace","Program counter register"],"a":2,"e":"In modern HotSpot JVMs, class metadata is stored in native-memory Metaspace."},{"q":"Which situation can cause a `StackOverflowError`?","o":["Excessive recursive method calls","Creating a large object on the heap","Dividing an integer by zero","Accessing an invalid array index"],"a":0,"e":"Deep or infinite recursion can exhaust the thread's stack."},{"q":"Which situation is most likely to cause an `OutOfMemoryError: Java heap space`?","o":["Excessive object allocation that exhausts available heap memory","Calling `Thread.sleep()`","Using an invalid cast","Dividing by zero"],"a":0,"e":"The heap can be exhausted when objects consume more memory than the JVM can provide."},{"q":"What is the output of this code?\n```\nclass A {\n    void show() {\n        System.out.println(\"A\");\n    }\n}\nclass B extends A {\n    void show() {\n        System.out.println(\"B\");\n    }\n}\npublic class Main {\n    public static void main(String[] args) {\n        A obj = new B();\n        obj.show();\n    }\n}\n```","o":["A","B","AB","Compilation error"],"a":1,"e":"Overridden instance methods are dynamically dispatched according to the runtime object type."},{"q":"Which method is used to compare two strings without considering case differences?","o":["`equals()`","`equalsIgnoreCase()`","`compare()`","`sameIgnoreCase()`"],"a":1,"e":"This method compares string contents while ignoring case differences."},{"q":"What is the output of this code?\n```\nStringBuilder sb = new StringBuilder(\"ABC\");\nsb.insert(1, \"X\");\nsb.delete(2, 3);\nSystem.out.println(sb);\n```","o":["AXBC","AXC","ABC","XABC"],"a":1,"e":"Insertion produces `AXBC`; deleting the range from index 2 inclusive to 3 exclusive removes `B`."},{"q":"Which Java mechanism allows a class to inherit a method implementation while also providing a different implementation for an interface default method with the same signature?","o":["Constructor chaining","Method overriding","Static binding","Type casting"],"a":1,"e":"A class can override an inherited default method to provide its own implementation."},{"q":"What is the output of this Java code?\n```\nclass A {\n    A() {\n        System.out.print(\"A \");\n    }\n}\nclass B extends A {\n    B() {\n        System.out.print(\"B \");\n    }\n}\npublic class Main {\n    public static void main(String[] args) {\n        new B();\n    }\n}\n```","o":["`B A`","`A B`","`A`","`B`"],"a":1,"e":"The superclass constructor executes before the subclass constructor."},{"q":"Which statement about constructor chaining is correct?","o":["`this()` and `super()` can both be the first statement in the same constructor.","`this()` must always appear after `super()`.","A constructor can explicitly invoke either `this()` or `super()`, but not both.","Constructors cannot invoke other constructors."],"a":2,"e":"Explicit constructor invocation must be the first statement. A constructor cannot contain both calls."},{"q":"What is the output of this code?\n```\nclass A {\n    private int x = 10;\n    int getX() {\n        return x;\n    }\n}\nclass B extends A {\n    int x = 20;\n}\npublic class Main {\n    public static void main(String[] args) {\n        B obj = new B();\n        System.out.println(obj.getX());\n    }\n}\n```","o":["10","20","30","Compilation error"],"a":0,"e":"The private field in `A` is separate from the field declared in `B`. The inherited method accesses `A`'s field."},{"q":"Which statement about covariant return types in Java is correct?","o":["An overriding method may return a subtype of the original reference return type.","An overriding method must return a primitive type.","An overriding method must return exactly the same class type.","Covariant returns are allowed only for static methods."],"a":0,"e":"Java allows an overriding method to return a more specific reference type."},{"q":"What happens when a class implements two interfaces that provide conflicting default methods with the same signature?","o":["The JVM chooses one randomly.","The class must resolve the conflict by overriding the method.","Both methods execute automatically.","The class cannot implement any interfaces."],"a":1,"e":"The implementing class must explicitly resolve conflicting inherited default methods."},{"q":"Which statement about private methods in Java interfaces is correct?","o":["They can be overridden by implementing classes.","They can be used only by static methods.","They can help share implementation among interface methods.","They must be abstract."],"a":2,"e":"Since Java 9, interfaces can contain private methods for sharing internal implementation."},{"q":"What is the output of this code?\n```\nclass A {\n    static void display() {\n        System.out.println(\"A\");\n    }\n}\nclass B extends A {\n    static void display() {\n        System.out.println(\"B\");\n    }\n}\npublic class Main {\n    public static void main(String[] args) {\n        A obj = new B();\n        obj.display();\n    }\n}\n```","o":["A","B","AB","Compilation error"],"a":0,"e":"Static method calls are resolved using the reference type, not the runtime object type."},{"q":"Which Java keyword prevents a method parameter from being reassigned within the method?","o":["`static`","`final`","`volatile`","`transient`"],"a":1,"e":"A final parameter cannot be reassigned inside the method, although a referenced object's contents may still be modified."},{"q":"What is the output of this code?\n```\nint x = 5;\nSystem.out.println(x << 2);\n```","o":["10","15","20","25"],"a":2,"e":"Left-shifting 5 by two positions gives 5 × 4 = 20."},{"q":"Which statement about the `volatile` keyword is correct?","o":["It makes all operations on a variable atomic.","It guarantees visibility of writes to subsequent reads of that variable under the Java Memory Model.","It prevents a variable from changing.","It automatically synchronizes all methods in a class."],"a":1,"e":"`volatile` provides visibility and ordering guarantees, but does not make compound operations such as `count++` atomic."},{"q":"What is the output of this code?\n```\nint count = 0;\nfor (int i = 0; i < 5; i++) {\n    if (i == 3) {\n        continue;\n    }\n    count++;\n}\nSystem.out.println(count);\n```","o":["3","4","5","2"],"a":1,"e":"The iteration with `i == 3` skips the increment, so the counter increases four times."},{"q":"Which method provides an atomic increment operation for an integer value shared across threads?","o":["`Integer.increment()`","`AtomicInteger.incrementAndGet()`","`Math.increment()`","`Thread.increment()`"],"a":1,"e":"`AtomicInteger.incrementAndGet()` performs an atomic increment and returns the updated value."},{"q":"What is the main purpose of `CountDownLatch` in Java concurrency?","o":["To lock a collection permanently","To allow one or more threads to wait until a specified number of events complete","To create a new thread for every task","To stop the JVM"],"a":1,"e":"Threads calling `await()` wait until the latch count reaches zero."},{"q":"Which concurrency utility allows a fixed number of threads to wait for one another at a common synchronization point?","o":["`Semaphore`","`CyclicBarrier`","`AtomicInteger`","`ThreadLocal`"],"a":1,"e":"`CyclicBarrier` synchronizes a group of threads at a barrier and can be reused."},{"q":"Which Java concurrency utility limits the number of threads that can simultaneously access a resource?","o":["`Semaphore`","`CountDownLatch`","`Future`","`ThreadLocal`"],"a":0,"e":"A semaphore uses permits to control concurrent access to a resource."},{"q":"What is the output of this code?\n```\nExecutorService executor =\n    Executors.newSingleThreadExecutor();\nFuture<Integer> future =\n    executor.submit(() -> 10 + 20);\nSystem.out.println(future.get());\nexecutor.shutdown();\n```","o":["10","20","30","Compilation error"],"a":2,"e":"The submitted callable returns 30, which is retrieved using `Future.get()`."},{"q":"Which statement about `ConcurrentHashMap` is correct?","o":["It permits null keys and null values.","It does not permit null keys or null values.","It maintains keys in sorted order.","It is always synchronized using one global lock for every operation."],"a":1,"e":"`ConcurrentHashMap` rejects null keys and values and supports concurrent operations."},{"q":"Which Java collection is most suitable for implementing a thread-safe blocking FIFO queue?","o":["`ArrayList`","`PriorityQueue`","`ArrayBlockingQueue`","`HashSet`"],"a":2,"e":"`ArrayBlockingQueue` is a bounded blocking queue that supports concurrent producer-consumer operations."},{"q":"What does the `join()` method do when invoked on a thread?","o":["Starts a new thread.","Waits for the specified thread to terminate.","Terminates the specified thread.","Releases all locks held by the current thread."],"a":1,"e":"`join()` makes the calling thread wait until the target thread completes."},{"q":"Which statement about `ThreadLocal` is correct?","o":["It shares one variable value across all threads.","It provides each thread with its own independent value.","It automatically creates a new JVM.","It guarantees synchronization between threads."],"a":1,"e":"`ThreadLocal` maintains a separate value for each accessing thread."},{"q":"What is the output of this code?\n```\nList<Integer> nums = Arrays.asList(2, 3, 4, 5);\nint result = nums.stream()\n    .filter(n -> n % 2 == 0)\n    .map(n -> n * n)\n    .reduce(0, Integer::sum);\nSystem.out.println(result);\n```","o":["13","20","29","45"],"a":2,"e":"The even values are 2 and 4. Their squares are 4 and 16, giving a sum of 20.\n\nCorrection: The correct option is B (20), not C."},{"q":"Which Stream operation is a short-circuiting terminal operation that checks whether at least one element matches a predicate?","o":["`map()`","`anyMatch()`","`sorted()`","`collect()`"],"a":1,"e":"`anyMatch()` returns true as soon as a matching element is found."},{"q":"Which Java Stream method produces a stream of unique elements based on their equality?","o":["`filter()`","`distinct()`","`unique()`","`removeDuplicates()`"],"a":1,"e":"`distinct()` removes duplicate elements according to `equals()` and `hashCode()`."},{"q":"What does the following Java Stream expression return?\n```\nList<Integer> nums = Arrays.asList(1, 2, 3, 4, 5);\nlong result = nums.stream()\n    .filter(n -> n > 2)\n    .count();\n```","o":["2","3","4","5"],"a":1,"e":"The values greater than 2 are 3, 4 and 5."},{"q":"Which collector is used to group stream elements according to a classification function?","o":["`Collectors.joining()`","`Collectors.groupingBy()`","`Collectors.counting()`","`Collectors.toList()`"],"a":1,"e":"`groupingBy()` collects stream elements into groups based on a classification function."},{"q":"Which Java Stream collector counts the number of elements in each group?","o":["`Collectors.summingInt()`","`Collectors.counting()`","`Collectors.mapping()`","`Collectors.joining()`"],"a":1,"e":"`counting()` returns a collector that counts elements, often used downstream of `groupingBy()`."},{"q":"What is the output of this code?\n```\nList<String> names =\n    Arrays.asList(\"Ram\", \"Ravi\", \"Raj\");\nString result = names.stream()\n    .filter(s -> s.startsWith(\"R\"))\n    .count() + \"\";\nSystem.out.println(result);\n```","o":["2","3","\"3\"","Compilation error"],"a":2,"e":"All three names start with R. The count is converted into a string by concatenating with `\"\"`."},{"q":"Which Java Stream operation is used to flatten nested streams into one stream?","o":["`map()`","`flatMap()`","`filter()`","`reduce()`"],"a":1,"e":"`flatMap()` transforms each element into a stream and combines those streams into one."},{"q":"Which method creates a sequential stream from a collection?","o":["`collection.parallel()`","`collection.stream()`","`collection.iteratorStream()`","`collection.createStream()`"],"a":1,"e":"The `stream()` method returns a sequential stream of the collection's elements."},{"q":"Which statement about parallel streams is correct?","o":["They always execute faster than sequential streams.","They may use multiple threads to process data.","They guarantee ordered execution of every operation.","They cannot process collections."],"a":1,"e":"Parallel streams can use multiple threads, but overhead and shared-state concerns may make them slower or unsafe for some workloads."},{"q":"Which Java class represents an optional value that may or may not be present?","o":["`Nullable`","`Optional`","`Maybe`","`Result`"],"a":1,"e":"`Optional<T>` explicitly represents the presence or absence of a value."},{"q":"What happens when `Optional.empty().get()` is called?","o":["Returns null","Returns zero","Throws `NoSuchElementException`","Returns an empty string"],"a":2,"e":"`get()` throws an exception when the optional contains no value."},{"q":"Which method executes a given action only when an `Optional` contains a value?","o":["`orElse()`","`ifPresent()`","`empty()`","`getOrNull()`"],"a":1,"e":"`ifPresent()` invokes the supplied consumer only when a value exists."},{"q":"Which JDBC method disables automatic transaction commits?","o":["`commit(false)`","`setAutoCommit(false)`","`rollback(true)`","`setTransaction(false)`"],"a":1,"e":"This allows several database operations to be executed as one explicit transaction."},{"q":"What is the purpose of JDBC's `rollback()` method?","o":["Permanently saves transaction changes","Undoes uncommitted transaction changes","Closes the database connection","Deletes the database"],"a":1,"e":"`rollback()` reverses changes made since the last commit or transaction boundary."},{"q":"Which JDBC interface is used to obtain metadata about database tables, columns and supported features?","o":["`ResultSet`","`DatabaseMetaData`","`PreparedStatement`","`CallableStatement`"],"a":1,"e":"`DatabaseMetaData` provides information about the database and its capabilities."},{"q":"Which JDBC interface is used to execute stored procedures?","o":["`Statement`","`ResultSet`","`CallableStatement`","`Connection`"],"a":2,"e":"`CallableStatement` supports calling database stored procedures and handling their parameters."},{"q":"Which JDBC method retrieves the number of rows affected by an `UPDATE` statement?","o":["`executeQuery()`","`executeUpdate()`","`getUpdateCount()` only","`getRowCount()`"],"a":1,"e":"`executeUpdate()` returns the affected-row count for update operations."},{"q":"Which approach is best for ensuring that a JDBC connection is closed automatically after use?","o":["Calling `System.exit()`","Using try-with-resources","Using `Thread.sleep()`","Declaring the connection static"],"a":1,"e":"JDBC resources such as `Connection`, `Statement` and `ResultSet` implement `AutoCloseable` and can be managed with try-with-resources."},{"q":"What is the output of this code?\n```\ntry {\n    System.out.print(\"A\");\n    throw new RuntimeException();\n} catch (RuntimeException e) {\n    System.out.print(\"B\");\n} finally {\n    System.out.print(\"C\");\n}\n```","o":["A","AB","AC","ABC"],"a":3,"e":"The try block prints A, the catch block prints B, and the finally block prints C."},{"q":"Which statement about exception handling is correct?","o":["A checked exception never needs to be handled.","A checked exception must be caught or declared by a method that can throw it.","Runtime exceptions must always be declared in a `throws` clause.","Errors must always be caught."],"a":1,"e":"Checked exceptions are subject to compile-time catch-or-declare requirements."},{"q":"Which exception is thrown when a program attempts to parse an invalid integer string?","o":["`NumberFormatException`","`ArithmeticException`","`IOException`","`IllegalMonitorStateException`"],"a":0,"e":"`Integer.parseInt()` throws this exception when the input is not a valid integer representation."},{"q":"Which statement about multi-catch in Java is correct?","o":["It uses separate catch blocks only.","It allows multiple exception types in one catch block using `|`.","It catches only checked exceptions.","It replaces the finally block."],"a":1,"e":"Multi-catch syntax such as `catch (IOException | SQLException e)` handles multiple exception types in one block."},{"q":"Which statement about try-with-resources is correct?","o":["It works only with arrays.","It automatically closes resources implementing `AutoCloseable`.","It cannot be combined with catch blocks.","It requires manual resource cleanup in all cases."],"a":1,"e":"Resources declared in a try-with-resources statement are closed automatically when the statement finishes."},{"q":"What is the output of this code?\n```\ntry {\n    int x = 10 / 0;\n} catch (ArithmeticException e) {\n    System.out.println(\"A\");\n} catch (Exception e) {\n    System.out.println(\"B\");\n}\n```","o":["A","B","AB","Compilation error"],"a":0,"e":"The arithmetic exception is caught by the first matching catch block."},{"q":"Which Java class provides a mechanism for creating a temporary file?","o":["`File.createTempFile()`","`File.makeTemporary()`","`TempFile.create()`","`Files.createTemporary()`"],"a":0,"e":"`File.createTempFile()` creates a temporary file. The `Files` class also provides temporary-file creation methods."},{"q":"Which class is designed to efficiently read lines of text from a file?","o":["`FileOutputStream`","`BufferedReader`","`ObjectOutputStream`","`DataOutputStream`"],"a":1,"e":"`BufferedReader.readLine()` reads text one line at a time efficiently."},{"q":"Which Java NIO class represents a file or directory path?","o":["`FileReader`","`Path`","`Scanner`","`FileWriter`"],"a":1,"e":"`Path` represents a file-system path and is commonly used with the `Files` utility class."},{"q":"Which Java NIO utility class provides methods such as `readAllLines()` and `copy()`?","o":["`Paths`","`Files`","`FileReader`","`FileInputStream`"],"a":1,"e":"`java.nio.file.Files` provides static utility methods for file operations."},{"q":"What is the purpose of the `transient` keyword in Java serialization?","o":["It makes a variable constant.","It prevents a field from being serialized by default.","It makes a method synchronized.","It creates a temporary object."],"a":1,"e":"Transient instance fields are skipped by default Java object serialization."},{"q":"Which statement about Java's `serialVersionUID` is correct?","o":["It stores the object's memory address.","It identifies the version of a serializable class for compatibility checking.","It counts the number of serialized objects.","It specifies the size of the object."],"a":1,"e":"`serialVersionUID` is used during deserialization to verify compatibility between the serialized object and the class definition."},{"q":"Which Java mechanism allows inspection of classes, methods and fields at runtime?","o":["Serialization","Reflection","Inheritance","Encapsulation"],"a":1,"e":"Reflection allows programs to inspect and interact with classes and their members at runtime."},{"q":"Which Java method obtains the runtime class object of an existing instance?","o":["`getType()`","`getClass()`","`classOf()`","`getObject()`"],"a":1,"e":"Every Java object inherits `getClass()` from `Object`."},{"q":"Which Java API can be used to create an instance dynamically using reflection?","o":["`Class.newInstance()` only","`Constructor.newInstance()`","`Object.create()`","`Class.createObject()`"],"a":1,"e":"Reflection provides `Constructor.newInstance()` for creating objects dynamically. The older `Class.newInstance()` method is deprecated."},{"q":"Which annotation indicates that a method is deprecated and should generally not be used in new code?","o":["`@Override`","`@Deprecated`","`@SuppressWarnings`","`@FunctionalInterface`"],"a":1,"e":"`@Deprecated` marks APIs that should generally be avoided in favor of alternatives."},{"q":"What is the output of this code?\n```\nint x = 10;\nint y = 20;\nSystem.out.println(x > 5 ? y > 15 ? 1 : 2 : 3);\n```","o":["1","2","3","Compilation error"],"a":0,"e":"The outer condition is true, and the inner condition is also true, so the result is 1."},{"q":"Which statement about Java's `finalize()` method is correct?","o":["It is guaranteed to execute immediately before garbage collection.","It is deprecated and should not be relied upon for resource cleanup.","It is called whenever a method returns.","It prevents an object from being garbage collected."],"a":1,"e":"Finalization is deprecated for removal because its timing and execution are unreliable."},{"q":"Which Java interface represents an object that can be used with the enhanced `for` loop?","o":["`Iterator`","`Iterable`","`Comparable`","`Serializable`"],"a":1,"e":"`Iterable` provides an iterator and enables enhanced `for` loop traversal."},{"q":"What is the output of this code?\n```\nList<Integer> list = new ArrayList<>(\n    Arrays.asList(1, 2, 3, 4, 5)\n);\nlist.removeIf(n -> n % 2 == 0);\nSystem.out.println(list);\n```","o":["`[2, 4]`","`[1, 2, 3, 4, 5]`","`[1, 3, 5]`","`[]`"],"a":2,"e":"`removeIf()` removes elements satisfying the predicate. Here, all even numbers are removed."},{"q":"Which Java method is used to create a new thread-safe immutable list from an existing collection?","o":["`Collections.synchronizedList()`","`List.copyOf()`","`Arrays.asList()`","`Collections.sort()`"],"a":1,"e":"`List.copyOf()` returns an unmodifiable list. It is not a guarantee of deep immutability if its elements themselves are mutable."},{"q":"Which Java collection is designed to store elements in a sorted order while supporting efficient insertion and removal?","o":["`HashSet`","`TreeSet`","`ArrayList`","`LinkedHashSet`"],"a":1,"e":"`TreeSet` uses a tree-based structure to maintain sorted unique elements, with O(log n) basic operations."},{"q":"Which method is used to compare two objects for ordering in a class implementing `Comparable`?","o":["`equals()`","`compareTo()`","`compare()`","`hashCode()`"],"a":1,"e":"`compareTo()` defines the natural ordering of objects."},{"q":"What is the output of this code?\n```\nString a = \"Java\";\nString b = \"Ja\" + \"va\";\nSystem.out.println(a == b);\n```","o":["true","false","null","Compilation error"],"a":0,"e":"Both are compile-time constant string expressions and refer to the same interned string literal."},{"q":"Which class is designed for high-performance integer arithmetic in atomic operations?","o":["`AtomicInteger`","`IntegerBuilder`","`ThreadInteger`","`ConcurrentInteger`"],"a":0,"e":"`AtomicInteger` provides atomic operations such as increment, decrement and compare-and-set."},{"q":"What is the purpose of `compareAndSet()` in Java atomic classes?","o":["It always increments a variable.","It updates a value only if the current value matches the expected value.","It sorts two values.","It synchronizes every method in the class."],"a":1,"e":"Compare-and-set performs an atomic conditional update, which is a foundation of lock-free algorithms."},{"q":"Which Java concurrency interface represents an asynchronous computation that may complete in the future?","o":["`Future`","`Runnable`","`Iterator`","`Comparable`"],"a":0,"e":"`Future` represents a pending or completed result and provides methods to retrieve or cancel the computation."},{"q":"Which Java class provides methods to combine asynchronous tasks and handle their results without manually blocking at every step?","o":["`StringBuilder`","`CompletableFuture`","`ArrayDeque`","`FileReader`"],"a":1,"e":"`CompletableFuture` supports asynchronous pipelines, chaining and combining computations."},{"q":"Which method of `CompletableFuture` transforms a completed result into another result asynchronously?","o":["`thenApplyAsync()`","`cancel()`","`isDone()`","`getNow()`"],"a":0,"e":"`thenApplyAsync()` applies a transformation to the previous stage's result asynchronously."},{"q":"Which statement about Java's `synchronized` keyword is correct?","o":["It guarantees that a method executes only once.","It provides mutual exclusion using an object's monitor.","It permanently locks the object.","It automatically creates a new thread."],"a":1,"e":"A synchronized block or method acquires a monitor lock, ensuring mutual exclusion for code using that same monitor."},{"q":"Which condition is necessary for a deadlock to occur in a system?","o":["At least one thread must be running.","Circular waiting must exist among threads or processes.","Every thread must finish successfully.","No resource can be shared."],"a":1,"e":"Circular wait is one of the four Coffman conditions necessary for deadlock."},{"q":"Which Java class can be used to schedule tasks for execution after a delay or periodically?","o":["`Timer`","`Scanner`","`StringTokenizer`","`FileReader`"],"a":0,"e":"`Timer` schedules tasks for one-time or repeated execution. `ScheduledExecutorService` is generally preferred for modern concurrent applications."},{"q":"Which Java API provides a mechanism for formatting strings using placeholders such as `%d` and `%s`?","o":["`StringBuilder`","`String.format()`","`StringTokenizer`","`String.split()`"],"a":1,"e":"`String.format()` creates formatted strings using format specifiers."},{"q":"Which statement about the Java Platform Module System is correct?","o":["It was introduced in Java 5.","It was introduced in Java 9.","It replaces the JVM.","It prevents all package access."],"a":1,"e":"The module system introduced modular application organization through declarations such as `module-info.java`."},{"q":"Which keyword is used in a module declaration to make a package accessible to other modules?","o":["`requires`","`exports`","`imports`","`opensAll`"],"a":1,"e":"`exports` makes a package accessible to other modules at compile time and runtime. `opens` serves a different purpose related to reflection."},{"q":"Which Java feature allows a switch statement or expression to match patterns and inspect types of objects?","o":["Reflection only","Pattern matching for switch","Method overloading","Constructor chaining"],"a":1,"e":"Modern Java supports pattern matching in switch constructs, enabling type-based matching and more expressive control flow."}];
(function(){
  const isJavaProgramming = () => document.getElementById("selectedModuleTitle")?.textContent.trim() === "Java Programming";
  const moduleTitle = document.getElementById("selectedModuleTitle");
  const revealControls = () => {
    if(isJavaProgramming()){
      document.getElementById("cppPremiumControls").hidden = false;
      document.getElementById("premiumUnavailable").hidden = true;
    }
  };
  new MutationObserver(revealControls).observe(moduleTitle, {childList:true, characterData:true, subtree:true});
  document.addEventListener("click", function(){ setTimeout(revealControls, 0); });
  document.addEventListener("click", function(event){
    if(event.target && event.target.id === "openCppPremium" && isJavaProgramming()){
      event.preventDefault(); event.stopImmediatePropagation();
      const level = document.getElementById("cppPremiumLevel").value;
      premiumQs = level === "easy" ? javaProgrammingPremiumEasyQs : level === "moderate" ? javaProgrammingPremiumModerateQs : javaProgrammingPremiumHardQs;
      premiumIndex = 0; premiumAnswers = {};
      document.getElementById("premiumUnavailable").hidden = true;
      document.getElementById("premiumPracticePanel").hidden = false;
      renderPremium();
    }
  }, true);
})();